package com.company.platform.analytics.application;
import com.company.platform.analytics.infrastructure.TenantContextProvider;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;
@Service public class KpiEngineService{private final JdbcTemplate jdbc;private final TenantContextProvider tenant;public KpiEngineService(JdbcTemplate j,TenantContextProvider t){jdbc=j;tenant=t;}private UUID t(){return tenant.currentTenantId();}public Map<String,Object> calculate(){UUID x=t();Map<String,Object> k=new LinkedHashMap<>();k.put("tenantId",x);k.put("sales",jdbc.queryForMap("SELECT COALESCE(SUM(total_amount),0) total,COALESCE(SUM(total_orders),0) orders FROM analytics_sales WHERE tenant_id=?",x));k.put("ticketAverage",jdbc.queryForObject("SELECT COALESCE(SUM(total_amount)/NULLIF(SUM(total_orders),0),0) FROM analytics_sales WHERE tenant_id=?",Object.class,x));k.put("revenue",jdbc.queryForObject("SELECT COALESCE(SUM(amount),0) FROM analytics_payments WHERE tenant_id=? AND status LIKE '%Captured%'",Object.class,x));k.put("refunds",jdbc.queryForObject("SELECT COALESCE(SUM(amount),0) FROM analytics_refunds WHERE tenant_id=?",Object.class,x));k.put("ordersByStatus",jdbc.queryForList("SELECT status,COUNT(*) count FROM analytics_orders WHERE tenant_id=? GROUP BY status",x));k.put("inventory",jdbc.queryForMap("SELECT COALESCE(SUM(available_quantity),0) available,COALESCE(SUM(reserved_quantity),0) reserved FROM analytics_inventory WHERE tenant_id=?",x));k.put("topProducts",jdbc.queryForList("SELECT product_id,SUM(units) units FROM analytics_product_sales WHERE tenant_id=? GROUP BY product_id ORDER BY units DESC LIMIT 10",x));k.put("topCategories",jdbc.queryForList("SELECT category_id,SUM(units) units FROM analytics_product_sales WHERE tenant_id=? AND category_id IS NOT NULL GROUP BY category_id ORDER BY units DESC LIMIT 10",x));return k;}public List<Map<String,Object>> trend(String period){String group=switch(period.toLowerCase()){case "week"->"date_trunc('week',period_date)";case "month"->"date_trunc('month',period_date)";case "quarter"->"date_trunc('quarter',period_date)";case "year"->"date_trunc('year',period_date)";default->"period_date";};return jdbc.queryForList("SELECT "+group+" period,SUM(total_amount) amount,SUM(total_orders) orders FROM analytics_sales WHERE tenant_id=? GROUP BY 1 ORDER BY 1",t());}}
